package io.knowledgebrain.learning;
import java.time.*;import java.util.*;
import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class MediaEvidenceMigrationIntegrationTest {
 String schema;JdbcTemplate sql;
 @AfterEach void cleanup(){if(schema!=null){assertTrue(schema.matches("media_evidence_test_[0-9a-f]{32}"));sql.execute("DROP SCHEMA "+schema+" CASCADE");}}
 @Test void v4NoteAndConceptRowsKeepIdsSnapshotsFingerprintsOutboxBytesAndTypedIsolation(){
  var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));schema="media_evidence_test_"+UUID.randomUUID().toString().replace("-","");ds.setCurrentSchema(schema);sql=new JdbcTemplate(ds);Flyway.configure().dataSource(ds).schemas(schema).locations("classpath:db/migration").target("4").load().migrate();var clock=Clock.systemUTC();var ids=new UuidV7(clock);var space=ids.next();var actor=ids.next();String trace="d".repeat(32);var roots=new RoadmapStore(ds,clock);var root=roots.create(space,actor,"Migration","",trace);root=roots.graph(space,root.roadmapId(),actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","Node","")),List.of()),trace);var roadmap=root.roadmapId();var node=root.nodes().getFirst().nodeId();var note=ids.next();var concept=ids.next();var notes=new LearningEvidenceStore(ds,clock,roots);var concepts=new ConceptEvidenceStore(ds,clock,roots);var ni=new LearningEvidenceStore.Input(node,note,3,"old note");var ci=new ConceptEvidenceStore.Input(node,space,concept,4,"old concept");String nk="a".repeat(32),ck="b".repeat(32);var n=notes.record(space,roadmap,actor,nk,ni,trace,()->new NoteReferenceClient.Reference(space,note,actor,3,"Old note","PRIVATE")).evidence();var c=concepts.record(space,roadmap,actor,ck,ci,trace,()->new ConceptReferenceClient.Reference(space,concept,space,actor,4,"Old concept","PRIVATE")).evidence();var prior=sql.queryForList("SELECT evidence_id,request_fingerprint FROM learning_evidence ORDER BY evidence_id");var events=new HashMap<UUID,byte[]>();sql.query("SELECT id,payload FROM outbox_event",(rs,i)->{events.put(rs.getObject(1,UUID.class),rs.getBytes(2));return 0;});
  Flyway.configure().dataSource(ds).schemas(schema).locations("classpath:db/migration").load().migrate();assertEquals(prior,sql.queryForList("SELECT evidence_id,request_fingerprint FROM learning_evidence ORDER BY evidence_id"));sql.query("SELECT id,payload FROM outbox_event",(rs,i)->{assertArrayEquals(events.get(rs.getObject(1,UUID.class)),rs.getBytes(2));return 0;});assertEquals(n,notes.record(space,roadmap,actor,nk,ni,trace,()->{fail();return null;}).evidence());assertEquals(c,concepts.record(space,roadmap,actor,ck,ci,trace,()->{fail();return null;}).evidence());var media=new MediaEvidenceStore(ds,clock,roots);assertTrue(media.page(space,roadmap,null,20).items().isEmpty());for(var id:List.of(n.evidenceId(),c.evidenceId()))assertEquals(404,assertThrows(ResponseStatusException.class,()->media.get(space,roadmap,id)).getStatusCode().value());var file=ids.next();var mi=new MediaEvidenceStore.Input(node,file,2,"file");for(var key:List.of(nk,ck))assertEquals(409,assertThrows(ResponseStatusException.class,()->media.record(space,roadmap,actor,key,mi,trace,()->{fail();return null;})).getStatusCode().value());var m=media.record(space,roadmap,actor,"c".repeat(32),mi,trace,()->new MediaReferenceClient.Reference(space,file,actor,2,"file.pdf","application/pdf",12,"a".repeat(64),"AVAILABLE","PRIVATE")).evidence();assertEquals(404,assertThrows(ResponseStatusException.class,()->notes.get(space,roadmap,m.evidenceId())).getStatusCode().value());assertEquals(404,assertThrows(ResponseStatusException.class,()->concepts.get(space,roadmap,m.evidenceId())).getStatusCode().value());assertEquals(n,notes.history(space,roadmap,n.evidenceId(),2,5).getFirst().snapshot());assertEquals(c,concepts.history(space,roadmap,c.evidenceId(),2,5).getFirst().snapshot());
 }
}
